/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        scwin.dateSetting();
        scwin.cgSearch((String(((dma_pageContext.get("ipt_curSh") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_curSh") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ipt_curSh") ?? "")) == null ? '' : ((dma_pageContext.get("ipt_curSh") ?? "")))), 'Y');
        $('input[name=ipt_isurNm1]').keypress(async function(e) {
                if (e.keyCode === 13) {
                    await scwin.search('1');
                }
        });
        $('input[name=rd_searchRadio]').bind("click", function() {
                $c.util.getComponent('ipt_curSh').setValue($(this).val());
                $('.paging').empty();
                const resetPaging = "<tr><td style='padding-left:5px'><img diabled src='/img/btn/btn-pprev.gif' alt=''></td><td style='padding-left:5px'><img src='/img/btn/btn-prev.gif' alt='' ></td><td class='bg_pagingbar'></td><td>1</td><td style='padding-left:5px'><img src='/img/btn/btn-next.gif' border='0' ></td><td style='padding-left:5px'><img src='/img/btn/btn-nnext.gif' alt='' ></a></td></tr>";
                $('.paging').append(resetPaging);
        });
        $c.util.getComponent("id_date").setStyle("display", "none");
        $c.util.getComponent("id_search").setStyle("display", "none");
        $c.util.getComponent("id_type").setStyle("display", "none");
        $c.util.getComponent("ipt_isurNm1").focus();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf40000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(srch vs excel) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":4
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf40000' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_stdCdGrntStartDd();
        scwin.init_datefmt_cal_stdCdGrntEndDd();
        scwin.init_datefmt_cal_startIsuDD();
        scwin.init_datefmt_cal_endIsuDD();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf40000.onpageload' });
    }
};

