/**
 * @method
 * @name dataTb_oncellclick
 * @description dataTb 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["mktNm"] !== '14' && r["mktNm"] !== '15' && r["mktNm"] !== '17') { await scwin.onPopupCode(r["mktNm"], r["stdCd"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_onPopupCode
 * @description on Popup Code 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_onPopupCode = async function () {
    const sbmOptions = {
        id: "tx_onPopupCode",
        method: "post",
        action: "/srch/srch.do?method=srchPopup",
        ref: "dma_onPopupCodeReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    try { return await $c.data.downFile("/srch/srch.do?method=ksdDownList", "", ($c.util.getComponent("dma_searchReq") ? $c.util.getComponent("dma_searchReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fnExcelDown
 * @description fn Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnExcelDown = async function () {
    try { return await $c.data.downFile("/down/excel.do?method=searchDownloadExcelFiles", "", ($c.util.getComponent("dma_fnExcelDownReq") ? $c.util.getComponent("dma_fnExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

