/**
 * @method
 * @name dateSetting
 * @description date Setting 처리
 * @returns {void}
 * @hidden N
 */
scwin.dateSetting = function () {
    const curDate = (String(((dma_pageContext.get("curDate") ?? "")) == null ? '' : ((dma_pageContext.get("curDate") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("curDate") ?? "")) == null ? '' : ((dma_pageContext.get("curDate") ?? ""))));
    const curYY = curDate.substring(0, 4);
    const curMM = curDate.substring(4, 6);
    const curDD = curDate.substring(6, 8);
    const intCurYY = Number(curYY);
    const intCurMM = Number(curMM);
    let bfOneYY = "";
    let bfOneMM = "";
    let calMM = intCurMM - 12;
    if (calMM < 0) {
        bfOneYY = intCurYY - 1;
        bfOneMM = 12 + calMM;
    } else {
        bfOneYY = intCurYY;
        bfOneMM = calMM;
    }
    let bfThreeYY = "";
    let bfThreeMM = "";
    calMM = intCurMM - 3;
    if (calMM < 0) {
        bfThreeYY = intCurYY - 1;
        bfThreeMM = 12 + calMM;
    } else {
        bfThreeYY = intCurYY;
        bfThreeMM = calMM;
    }
    let bfSixYY = "";
    let bfSixMM = "";
    calMM = intCurMM - 6;
    if (calMM < 0) {
        bfSixYY = intCurYY - 1;
        bfSixMM = 12 + calMM;
    } else {
        bfSixYY = intCurYY;
        bfSixMM = calMM;
    }
    const oneDD = new Date(bfOneYY, bfOneMM, curDD);
    const threeDD = new Date(bfThreeYY, bfThreeMM, curDD);
    const sixDD = new Date(bfSixYY, bfSixMM, curDD);
    if (Number(bfOneMM) < 10) {
        bfOneMM = "0" + bfOneMM;
    }
    if (Number(bfThreeMM) < 10) {
        bfThreeMM = "0" + bfThreeMM;
    }
    if (Number(bfSixMM) < 10) {
        bfSixMM = "0" + bfSixMM;
    }
    const oneD = (Number(oneDD.getMonth()) < 10) ? ("0" + oneDD.getMonth()) : oneDD.getMonth();
    const ThD = (Number(threeDD.getMonth()) < 10) ? ("0" + threeDD.getMonth()) : threeDD.getMonth();
    const SxD = (Number(sixDD.getMonth()) < 10) ? ("0" + sixDD.getMonth()) : sixDD.getMonth();
    const oneDt = (Number(oneDD.getDate()) < 10) ? ("0" + oneDD.getDate()) : oneDD.getDate();
    const ThDt = (Number(threeDD.getDate()) < 10) ? ("0" + threeDD.getDate()) : threeDD.getDate();
    const SxDt = (Number(sixDD.getDate()) < 10) ? ("0" + sixDD.getDate()) : sixDD.getDate();
    const bfOneDate = oneDD.getFullYear() + oneD + oneDt;
    const bfThreeDate = threeDD.getFullYear() + ThD + ThDt;
    const bfSixDate = sixDD.getFullYear() + SxD + SxDt;
    $c.util.getComponent('dma_hiddenStore').set('ipt_hdOneDate', bfOneDate);
    $c.util.getComponent('dma_hiddenStore').set('ipt_hdThreeDate', bfThreeDate);
    $c.util.getComponent('dma_hiddenStore').set('ipt_hdSixDate', bfSixDate);
};

/**
 * @method
 * @name cgSearch
 * @description cg Search 처리
 * @param {Number} idx idx
 * @param {*} check check
 * @returns {void}
 * @hidden N
 */
scwin.cgSearch = function (idx, check) {
    if (idx === '3' || idx === '4' || idx === '5' || idx === '6' || idx === '7' || idx === '8' || idx === '10' || idx === '11' || idx === '16' || idx === '18') {
        $c.util.getComponent("id_isu_dd").setStyle("display", "");
    } else {
        $c.util.getComponent("id_isu_dd").setStyle("display", "none");
    }
    const gubun = $c.util.getComponent("dma_onPopupCodeReq").get("gubunRadio");
    $('tr[name=trSearch]').attr("style", "display:none;");
    if (gubun === '1') {
        $c.util.getComponent('ipt_curSh').setValue('1');
        $('input[name=rd_searchRadio][value="' + idx + '"]').attr("checked", true);
        $c.util.getComponent("id_isur").setStyle("display", "");
        $c.util.getComponent("ipt_isurNm1").focus();
    } else {
        if (gubun === '2') {
            $c.util.getComponent('ipt_curSh').setValue('1');
            $('input[name=rd_searchRadio][value="' + idx + '"]').attr("checked", true);
            $c.util.getComponent("id_com").setStyle("display", "");
        } else {
            if (gubun === '3') {
                $('input[name=rd_searchRadio][value="' + idx + '"]').attr("checked", true);
                $c.util.getComponent("id_com").setStyle("display", "");
                $c.util.getComponent("id_type").setStyle("display", "");
                $c.util.getComponent("id_date").setStyle("display", "");
                $('input[name=searchDateRadio][value=4]').attr("checked", true);
                /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
                $c.util.getComponent('ipt_dnldInstTpCd').setValue(scwin.LPAD(idx));
            } else {
                $c.util.getComponent('ipt_curSh').setValue('1');
                $('input[name=rd_searchRadio][value=1]').attr("checked", true);
                $c.util.getComponent("id_isur").setStyle("display", "");
            }
        }
    }
};

/**
 * @method
 * @name LPAD
 * @description LPAD 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.LPAD = function (val) {
    if (val < 10) {
        return "0" + "" + val;
    } else {
        return val;
    }
};

