/**
 * @method
 * @name search
 * @description search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (idx) {
    let diff;
    const gubun = $c.util.getComponent("dma_onPopupCodeReq").get("gubunRadio");
    if (gubun === '1') {
        if (($c.util.getComponent('ipt_isurNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_isurNm1').getValue())) === '') {
            await $c.win.alert("한글종목명 및 표준코드을 입력하세요.");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isurNm1').getValue()) <= 2) {
            await $c.win.alert("한글종목명 및 표준코드을 확인하세요");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        $('input[name=rd_searchRadio][value=1]').attr("checked", true);
        $c.util.getComponent('ipt_isurNm').setValue(($c.util.getComponent("ipt_isurNm1").getValue() || ''));
        if (($c.util.getComponent('cal_stdCdGrntStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntStartDd').getValue())) !== '' || ($c.util.getComponent('cal_stdCdGrntEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntEndDd').getValue())) !== '') {
            if (($c.util.getComponent('cal_stdCdGrntStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntStartDd').getValue())) === '' || ($c.util.getComponent('cal_stdCdGrntEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntEndDd').getValue())) === '') {
                await $c.win.alert("조회기간(코드부여일)의 시작/종료를 정확히 입력하셔야합니다.");
                return;
            } else {
                diff = $c.date.diffDate($c.util.getComponent('cal_stdCdGrntStartDd').getValue(), $c.util.getComponent('cal_stdCdGrntEndDd').getValue());
                if (diff > 92) {
                    await $c.win.alert("조회기간(코드부여일)은 3개월 이내로만 가능합니다.");
                    return;
                }
            }
        } else {
            if (($c.util.getComponent('cal_startIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_startIsuDD').getValue())) !== '' || ($c.util.getComponent('cal_endIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_endIsuDD').getValue())) !== '') {
                if (($c.util.getComponent('cal_startIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_startIsuDD').getValue())) === '' || ($c.util.getComponent('cal_endIsuDD').getValue() == null ? '' : String($c.util.getComponent('cal_endIsuDD').getValue())) === '') {
                    await $c.win.alert("조회기간(발행일)의 시작/종료를 정확히 입력하셔야합니다.");
                    return;
                } else {
                    diff = $c.date.diffDate($c.util.getComponent('cal_startIsuDD').getValue(), $c.util.getComponent('cal_endIsuDD').getValue());
                    if (diff > 92) {
                        await $c.win.alert("조회기간(발행일)은 3개월 이내로만 가능합니다.");
                        return;
                    }
                }
            } else {
                if (dma_hiddenStore.get("startDD") === "" && dma_hiddenStore.get("endDD") === "" && ($c.util.getComponent('cal_stdCdGrntStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntStartDd').getValue())) === '' && ($c.util.getComponent('cal_stdCdGrntEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntEndDd').getValue())) === '') {
                    await $c.win.alert("조회기간을 입력하셔야합니다.");
                    return;
                }
            }
        }
    } else {
        if (gubun === '2') {
            if (($c.util.getComponent('ipt_comNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm1').getValue())) === '') {
                await $c.win.alert("발행기관을 선택하세요.");
                return;
            }
            $('input[name=rd_searchRadio][value=1]').attr("checked", true);
            $c.util.getComponent('ipt_isurCd').setValue(($c.util.getComponent("ipt_isurCd1").getValue() || ''));
            $c.util.getComponent('ipt_comNm').setValue(($c.util.getComponent("ipt_comNm1").getValue() || ''));
        } else {
            if (gubun === '3') {
                $c.util.getComponent('ipt_isurCd').setValue(($c.util.getComponent("ipt_isurCd1").getValue() || ''));
                $c.util.getComponent('ipt_comNm').setValue(($c.util.getComponent("ipt_comNm1").getValue() || ''));
            }
        }
    }
    const frm = (document.JLDINF40000 || { elements: [] });
    diff = $c.date.diffDate($c.util.getComponent('cal_stdCdGrntStartDd').getValue(), $c.util.getComponent('cal_stdCdGrntEndDd').getValue());
    if (diff > 365) {
        await $c.win.alert("조회 기간은 1년 이내로만 가능합니다.");
        $c.util.getComponent("cal_stdCdGrntStartDd").focus();
        return;
    }
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    frm.action = "/srch/srch.do?method=ksdDownList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name fnDownloadChk
 * @description fn Download Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownloadChk = async function () {
    const form = (document.JLDINF40000 || { elements: [] });
    if (($c.util.getComponent('cal_stdCdGrntStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntStartDd').getValue())) === '') {
        await $c.win.alert('코드부여일을 1년 이내로 설정하여야\n\r사용이 가능합니다.');
        $c.util.getComponent("cal_stdCdGrntStartDd").focus();
        return;
    } else {
        if (($c.util.getComponent('cal_stdCdGrntEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntEndDd').getValue())) === '') {
            await $c.win.alert('코드부여일을 1년 이내로 설정하여야\n\r사용이 가능합니다.');
            $c.util.getComponent("cal_stdCdGrntEndDd").focus();
            return;
        } else {
            const startD = $c.util.getComponent('cal_stdCdGrntStartDd').getValue();
            const startN = parseInt(startD.substr(4, 2), 10) - 1;
            const startT = new Date(startD.substr(0, 4), startN, startD.substr(6, 2));
            const endD = $c.util.getComponent('cal_stdCdGrntEndDd').getValue();
            const endN = parseInt(endD.substr(4, 2), 10) - 1;
            const endT = new Date(endD.substr(0, 4), endN, endD.substr(6, 2));
            const apDate = new Date(endT - 365 * 1000 * 60 * 60 * 24);
            if (apDate - startT > 0) {
                await $c.win.alert('코드부여일을 1년 이내로 설정하여야\n\r사용이 가능합니다.');
                $c.util.getComponent("cal_stdCdGrntStartDd").focus();
                return;
            }
        }
    }
    fn_downInfoWin(form);
    await $c.win.alert("조회 내용이 없습니다.");
};

